$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest

$root=(Get-Location).Path
if(-not(Test-Path(Join-Path $root 'pubspec.yaml'))){
  throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8=New-Object System.Text.UTF8Encoding($false)
$stamp=Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot=Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/access_control_phase1_$stamp"

function Read-ProjectFile([string]$p){
  $f=Join-Path $root $p
  if(-not(Test-Path $f)){throw "Required file not found: $p"}
  [IO.File]::ReadAllText($f).Replace("`r`n","`n")
}

function Write-ProjectFile([string]$p,[string]$c){
  $f=Join-Path $root $p
  New-Item -ItemType Directory -Path(Split-Path $f -Parent)-Force|Out-Null
  [IO.File]::WriteAllText($f,$c,$utf8)
  Write-Host "Created/updated: $p" -ForegroundColor Green
}

function Backup-ProjectFile([string]$p){
  $s=Join-Path $root $p
  if(-not(Test-Path $s)){return}
  $d=Join-Path $backupRoot $p
  New-Item -ItemType Directory -Path(Split-Path $d -Parent)-Force|Out-Null
  Copy-Item $s $d -Force
}

function Add-Import([string]$c,[string]$line){
  if($c.Contains($line)){return $c}
  $m=[regex]::Matches($c,"(?m)^import\s+['""].+?['""];\s*$")
  if($m.Count-eq 0){throw "Import block not found: $line"}
  $x=$m[$m.Count-1]
  $c.Insert($x.Index+$x.Length,"`n$line")
}

function Insert-BeforeFirst([string]$c,[string]$marker,[string[]]$patterns,[string]$block){
  if($c.Contains($marker)){return $c}
  foreach($p in $patterns){
    $m=[regex]::Match($c,$p)
    if($m.Success){return $c.Insert($m.Index,$block)}
  }
  throw "Registration anchor not found: $marker"
}

$payloads=@{
'lib/features/access_control/domain/entities/app_permission.dart'=''
'lib/features/access_control/domain/entities/app_role_entity.dart'=''
'lib/features/access_control/data/models/app_role_model.dart'=''
'lib/features/access_control/domain/repositories/app_role_repository.dart'=''
'lib/features/access_control/data/repositories/app_role_repository_impl.dart'=''
'lib/features/access_control/presentation/bloc/app_role_bloc.dart'=''
'lib/features/access_control/presentation/pages/app_role_form_page.dart'=''
'lib/features/access_control/presentation/pages/roles_permissions_page.dart'=''
}
$paths='lib/core/constants/firestore_paths.dart'
$sl='lib/core/di/service_locator.dart'
$sidebar='lib/features/dashboard/presentation/widgets/sidebar.dart'

foreach($p in @($paths,$sl,$sidebar)+$payloads.Keys){
  Backup-ProjectFile $p
}

foreach($item in $payloads.GetEnumerator()){
  $text=[Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String($item.Value)
  )
  Write-ProjectFile $item.Key $text
}

$c=Read-ProjectFile $paths
if(-not$c.Contains('static const String appRoles')){
  $i=$c.LastIndexOf('}')
  if($i-lt 0){throw 'FirestorePaths closing brace not found.'}
  $c=$c.Insert($i,"  static const String appRoles = 'app_roles';`n")
}
Write-ProjectFile $paths $c

$c=Read-ProjectFile $sl
foreach($line in @(
"import '../../features/access_control/data/repositories/app_role_repository_impl.dart';",
"import '../../features/access_control/domain/repositories/app_role_repository.dart';",
"import '../../features/access_control/presentation/bloc/app_role_bloc.dart';"
)){
  $c=Add-Import $c $line
}

$repoReg=@'
  sl.registerLazySingleton<AppRoleRepository>(
    () => AppRoleRepositoryImpl(
      sl<FirebaseFirestoreService>(),
    ),
  );

'@

$c=Insert-BeforeFirst $c 'registerLazySingleton<AppRoleRepository>' @(
'(?m)^\s*sl\.registerLazySingleton<ParentNotificationRepository>',
'(?m)^\s*sl\.registerLazySingleton<ParentCommunicationService>',
'(?m)^\s*sl\.registerLazySingleton<ParentPortalRepository>',
'(?m)^\s*sl\.registerLazySingleton<'
) $repoReg

$blocReg=@'
  sl.registerFactory<AppRoleBloc>(
    () => AppRoleBloc(
      sl<AppRoleRepository>(),
    ),
  );

'@

$c=Insert-BeforeFirst $c 'registerFactory<AppRoleBloc>' @(
'(?m)^\s*sl\.registerFactory<ParentNotificationBloc>',
'(?m)^\s*sl\.registerFactory<ParentPortalBloc>',
'(?m)^\s*sl\.registerFactory<'
) $blocReg

Write-ProjectFile $sl $c

$c=Read-ProjectFile $sidebar
$c=Add-Import $c "import '../../../access_control/presentation/pages/roles_permissions_page.dart';"

if(-not$c.Contains('const RolesPermissionsPage()')){
  $settingsPattern=@'
(?ms)
(\s*)_menuTile\(
\s*context,
\s*icon:\s*Icons\.settings,
\s*title:\s*'Settings',
'@

  $m=[regex]::Match(
    $c,
    $settingsPattern,
    [System.Text.RegularExpressions.RegexOptions]::IgnorePatternWhitespace
  )

  if(-not$m.Success){
    throw 'Settings sidebar anchor not found.'
  }

  $indent=$m.Groups[1].Value
  $block=@"
${indent}_menuTile(
${indent}  context,
${indent}  icon: Icons.admin_panel_settings_outlined,
${indent}  title: 'Roles & Permissions',
${indent}  onTap: () {
${indent}    Navigator.of(context).push(
${indent}      MaterialPageRoute<void>(
${indent}        builder: (_) => const RolesPermissionsPage(),
${indent}      ),
${indent}    );
${indent}  },
${indent}),
"@

  $c=$c.Insert($m.Index,$block)
}

Write-ProjectFile $sidebar $c

Write-Host "`nRunning dart format..." -ForegroundColor Cyan
& dart format $paths $sl $sidebar 'lib/features/access_control'
if($LASTEXITCODE-ne 0){throw 'dart format failed.'}

Write-Host "`nRunning flutter analyze..." -ForegroundColor Cyan
& flutter analyze
if($LASTEXITCODE-ne 0){
  throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host "`nRoles and Permissions Phase 1 Core Setup completed successfully." -ForegroundColor Green
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
